#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int* twoSum(int* numbers, int numbersSize, int target, int* returnSize) {
    int left = 0, right = numbersSize - 1;
    while (left < right) {
        int total = numbers[left] + numbers[right];
        if (total == target) {
            int* result = (int*)malloc(2 * sizeof(int));
            result[0] = left + 1;
            result[1] = right + 1;
            *returnSize = 2;
            return result;
        }
        if (total < target) left++;
        else right--;
    }
    *returnSize = 0;
    return NULL;
}

