    static String[] readArrayRaw(String s) {
        s = s.trim();
        if (s.equals("[]")) return new String[0];
        s = s.substring(1, s.length() - 1);
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) { parts.add(s.substring(start, i).trim()); start = i + 1; }
        }
        parts.add(s.substring(start).trim());
        return parts.toArray(new String[0]);
    }
    static int[] toIntArray(String s) {
        String[] parts = readArrayRaw(s);
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i]);
        return a;
    }
